const PixelAsset &book_of_answers_asset(BookOfAnswersAssetId id)
{
    switch (id) {
    case BookOfAnswersAssetId::Home: {
        static constexpr PixelAsset asset = {300, 385, kHomeData};
        return asset;
    }
    case BookOfAnswersAssetId::HomeAlt: {
        static constexpr PixelAsset asset = {300, 385, kHomeAltData};
        return asset;
    }
    case BookOfAnswersAssetId::ShakeLeft: {
        static constexpr PixelAsset asset = {320, 380, kShakeLeftData};
        return asset;
    }
    case BookOfAnswersAssetId::ShakeRight: {
        static constexpr PixelAsset asset = {320, 380, kShakeRightData};
        return asset;
    }
    case BookOfAnswersAssetId::ShakeLongerPrimary: {
        static constexpr PixelAsset asset = {310, 394, kShakeLongerPrimaryData};
        return asset;
    }
    case BookOfAnswersAssetId::ShakeLongerSecondary: {
        static constexpr PixelAsset asset = {310, 394, kShakeLongerSecondaryData};
        return asset;
    }
    case BookOfAnswersAssetId::Thinking: {
        static constexpr PixelAsset asset = {300, 374, kThinkingData};
        return asset;
    }
    case BookOfAnswersAssetId::ThinkingAlt: {
        static constexpr PixelAsset asset = {300, 374, kThinkingAltData};
        return asset;
    }
    case BookOfAnswersAssetId::Revealing: {
        static constexpr PixelAsset asset = {300, 374, kRevealingData};
        return asset;
    }
    case BookOfAnswersAssetId::RevealingAlt: {
        static constexpr PixelAsset asset = {300, 374, kRevealingAltData};
        return asset;
    }
    case BookOfAnswersAssetId::MessageResult: {
        static constexpr PixelAsset asset = {310, 322, kMessageResultData};
        return asset;
    }
    case BookOfAnswersAssetId::MessageResultAlt: {
        static constexpr PixelAsset asset = {310, 322, kMessageResultAltData};
        return asset;
    }
    case BookOfAnswersAssetId::CrystalResultPrimary: {
        static constexpr PixelAsset asset = {440, 570, kCrystalResultPrimaryData};
        return asset;
    }
    case BookOfAnswersAssetId::CrystalResultSecondary: {
        static constexpr PixelAsset asset = {440, 570, kCrystalResultSecondaryData};
        return asset;
    }
    }
    static constexpr PixelAsset fallback = {300, 385, kHomeData};
    return fallback;
}
